// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    Recorder rec;

    function setUp() public { 
        c = new airPort();
        rec = new Recorder();
    }

    // fuzzed params: from address, one recipient address, uint value, and a flag to choose number of tos (1..3)
    function testFuzz_property(address from, address to, uint256 v, uint8 count) public {
        // keep addresses non-zero; allow count 1..3 to keep number of calls small and deterministic
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        uint256 n = bound(count, 1, 3);

        // build tos array of length n filled with `to`
        address[] memory tos = new address[](n);
        for (uint i = 0; i < n; i++) tos[i] = to;

        // call C.transfer routing to our Recorder as the callee (caddress)
        // we pass rec's address so C will call into functions on Recorder
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general invariant: for any non-empty tos, the reference C always calls the callee with selector
        // bytes4(keccak256("transferFrom(address,address,uint256)")) for each element. Recorder records the
        // last selector it received (and a counter). We assert that the selector recorded equals the expected
        // transferFrom selector when the call succeeded (ok==true). The mutant that changed the selector will
        // cause Recorder to observe a different selector for some inputs and thus fail this assertion.

        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // If C performed the calls and returned (ok==true), Recorder.counter should equal n and lastSelector should be expected.
        // If C reverted, ok==false; the correct contract only reverts when _tos.length == 0 which we excluded, so ok must be true.
        assertTrue(ok && rec.callCount() == n && rec.lastSelector() == expected);
    }
}

// Recorder matches the selector that reference C encodes with encodeWithSelector(id, from, _tos[i], v)
contract Recorder {
    uint256 public count;
    bytes4 public lastSel;
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;

    // declare the exact function so Solidity will decode and route the call to this implementation
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        count += 1;
        // record selector by reading msg.sig
        lastSel = msg.sig;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }

    // getters for the test to read
    function callCount() external view returns (uint256) { return count; }
    function lastSelector() external view returns (bytes4) { return lastSel; }
}
